#define _GNU_SOURCE
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>
#include <unistd.h>
#include <sched.h>

#define MR 6
#define NR 16
#define KC 256
#define MC 96
#define NCMAX 4096
#define MAXT 64
#define SPIN_LIMIT (1L << 22)

typedef float v8 __attribute__((vector_size(32)));

static inline v8 ldu(const float *p) { v8 v; memcpy(&v, p, sizeof v); return v; }
static inline void stu(float *p, v8 v) { memcpy(p, &v, sizeof v); }

static inline void cpu_relax(void)
{
#if defined(__x86_64__) || defined(__i386__)
    __builtin_ia32_pause();
#elif defined(__aarch64__)
    __asm__ __volatile__("yield");
#endif
}

#if defined(__x86_64__) && defined(__AVX2__) && defined(__FMA__)

#define STEP(b0, b1, a0, a1, a2, a3, a4, a5)            \
    "vmovups " #b0 "(%[b]), %%ymm12\n\t"                \
    "vmovups " #b1 "(%[b]), %%ymm13\n\t"                \
    "vbroadcastss " #a0 "(%[a]), %%ymm14\n\t"           \
    "vfmadd231ps %%ymm12, %%ymm14, %%ymm0\n\t"          \
    "vfmadd231ps %%ymm13, %%ymm14, %%ymm1\n\t"          \
    "vbroadcastss " #a1 "(%[a]), %%ymm15\n\t"           \
    "vfmadd231ps %%ymm12, %%ymm15, %%ymm2\n\t"          \
    "vfmadd231ps %%ymm13, %%ymm15, %%ymm3\n\t"          \
    "vbroadcastss " #a2 "(%[a]), %%ymm14\n\t"           \
    "vfmadd231ps %%ymm12, %%ymm14, %%ymm4\n\t"          \
    "vfmadd231ps %%ymm13, %%ymm14, %%ymm5\n\t"          \
    "vbroadcastss " #a3 "(%[a]), %%ymm15\n\t"           \
    "vfmadd231ps %%ymm12, %%ymm15, %%ymm6\n\t"          \
    "vfmadd231ps %%ymm13, %%ymm15, %%ymm7\n\t"          \
    "vbroadcastss " #a4 "(%[a]), %%ymm14\n\t"           \
    "vfmadd231ps %%ymm12, %%ymm14, %%ymm8\n\t"          \
    "vfmadd231ps %%ymm13, %%ymm14, %%ymm9\n\t"          \
    "vbroadcastss " #a5 "(%[a]), %%ymm15\n\t"           \
    "vfmadd231ps %%ymm12, %%ymm15, %%ymm10\n\t"         \
    "vfmadd231ps %%ymm13, %%ymm15, %%ymm11\n\t"

/* out[MR][NR] = Apanel(MR x kc) * Bpanel(kc x NR). */
static void micro(long kc, const float *a, const float *b, float *out)
{
    long k4 = kc >> 2, kr = kc & 3;
    __asm__ volatile(
        "vxorps %%ymm0, %%ymm0, %%ymm0\n\t"
        "vxorps %%ymm1, %%ymm1, %%ymm1\n\t"
        "vxorps %%ymm2, %%ymm2, %%ymm2\n\t"
        "vxorps %%ymm3, %%ymm3, %%ymm3\n\t"
        "vxorps %%ymm4, %%ymm4, %%ymm4\n\t"
        "vxorps %%ymm5, %%ymm5, %%ymm5\n\t"
        "vxorps %%ymm6, %%ymm6, %%ymm6\n\t"
        "vxorps %%ymm7, %%ymm7, %%ymm7\n\t"
        "vxorps %%ymm8, %%ymm8, %%ymm8\n\t"
        "vxorps %%ymm9, %%ymm9, %%ymm9\n\t"
        "vxorps %%ymm10, %%ymm10, %%ymm10\n\t"
        "vxorps %%ymm11, %%ymm11, %%ymm11\n\t"
        "test %[k4], %[k4]\n\t"
        "jz 2f\n\t"
        ".p2align 5\n"
        "1:\n\t"
        "prefetcht0 384(%[a])\n\t"
        STEP(0, 32, 0, 4, 8, 12, 16, 20)
        STEP(64, 96, 24, 28, 32, 36, 40, 44)
        "prefetcht0 448(%[a])\n\t"
        STEP(128, 160, 48, 52, 56, 60, 64, 68)
        STEP(192, 224, 72, 76, 80, 84, 88, 92)
        "add $96, %[a]\n\t"
        "add $256, %[b]\n\t"
        "dec %[k4]\n\t"
        "jnz 1b\n"
        "2:\n\t"
        "test %[kr], %[kr]\n\t"
        "jz 4f\n"
        "3:\n\t"
        STEP(0, 32, 0, 4, 8, 12, 16, 20)
        "add $24, %[a]\n\t"
        "add $64, %[b]\n\t"
        "dec %[kr]\n\t"
        "jnz 3b\n"
        "4:\n\t"
        "vmovups %%ymm0, 0(%[o])\n\t"
        "vmovups %%ymm1, 32(%[o])\n\t"
        "vmovups %%ymm2, 64(%[o])\n\t"
        "vmovups %%ymm3, 96(%[o])\n\t"
        "vmovups %%ymm4, 128(%[o])\n\t"
        "vmovups %%ymm5, 160(%[o])\n\t"
        "vmovups %%ymm6, 192(%[o])\n\t"
        "vmovups %%ymm7, 224(%[o])\n\t"
        "vmovups %%ymm8, 256(%[o])\n\t"
        "vmovups %%ymm9, 288(%[o])\n\t"
        "vmovups %%ymm10, 320(%[o])\n\t"
        "vmovups %%ymm11, 352(%[o])\n\t"
        : [a] "+r"(a), [b] "+r"(b), [k4] "+r"(k4), [kr] "+r"(kr)
        : [o] "r"(out)
        : "xmm0", "xmm1", "xmm2", "xmm3", "xmm4", "xmm5", "xmm6", "xmm7",
          "xmm8", "xmm9", "xmm10", "xmm11", "xmm12", "xmm13", "xmm14", "xmm15",
          "memory", "cc");
}

#else

/* out[MR][NR] = Apanel(MR x kc) * Bpanel(kc x NR). */
static void micro(long kc, const float *restrict a, const float *restrict b, float *restrict out)
{
    v8 c00 = {0}, c01 = {0}, c10 = {0}, c11 = {0}, c20 = {0}, c21 = {0};
    v8 c30 = {0}, c31 = {0}, c40 = {0}, c41 = {0}, c50 = {0}, c51 = {0};
    for (long k = 0; k < kc; k++) {
        v8 b0 = ldu(b), b1 = ldu(b + 8);
        c00 += a[0] * b0; c01 += a[0] * b1;
        c10 += a[1] * b0; c11 += a[1] * b1;
        c20 += a[2] * b0; c21 += a[2] * b1;
        c30 += a[3] * b0; c31 += a[3] * b1;
        c40 += a[4] * b0; c41 += a[4] * b1;
        c50 += a[5] * b0; c51 += a[5] * b1;
        a += MR;
        b += NR;
    }
    stu(out + 0, c00);  stu(out + 8, c01);
    stu(out + 16, c10); stu(out + 24, c11);
    stu(out + 32, c20); stu(out + 40, c21);
    stu(out + 48, c30); stu(out + 56, c31);
    stu(out + 64, c40); stu(out + 72, c41);
    stu(out + 80, c50); stu(out + 88, c51);
}

#endif

static inline void store_full(float *c, int ldc, const float *t, int acc)
{
    for (int i = 0; i < MR; i++) {
        float *p = c + (size_t)i * ldc;
        v8 x0 = ldu(t + i * NR), x1 = ldu(t + i * NR + 8);
        if (acc) {
            x0 += ldu(p);
            x1 += ldu(p + 8);
        }
        stu(p, x0);
        stu(p + 8, x1);
    }
}

static void store_edge(float *c, int ldc, const float *t, int mr, int nr, int acc)
{
    for (int i = 0; i < mr; i++) {
        float *p = c + (size_t)i * ldc;
        const float *s = t + i * NR;
        if (acc)
            for (int j = 0; j < nr; j++) p[j] += s[j];
        else
            for (int j = 0; j < nr; j++) p[j] = s[j];
    }
}

/* Packs an mc x kc block of A into MR-row panels, zero-padding the last one. */
static void pack_a(const float *A, int n, int i0, int mc, int p0, int kc, float *restrict Ap)
{
    for (int ip = 0; ip < mc; ip += MR) {
        int rows = mc - ip < MR ? mc - ip : MR;
        float *d = Ap + (size_t)ip * kc;
        const float *s = A + (size_t)(i0 + ip) * n + p0;
        if (rows == MR) {
            const float *s0 = s, *s1 = s + n, *s2 = s + 2 * (size_t)n;
            const float *s3 = s + 3 * (size_t)n, *s4 = s + 4 * (size_t)n, *s5 = s + 5 * (size_t)n;
            for (int k = 0; k < kc; k++) {
                d[0] = s0[k]; d[1] = s1[k]; d[2] = s2[k];
                d[3] = s3[k]; d[4] = s4[k]; d[5] = s5[k];
                d += MR;
            }
        } else {
            for (int k = 0; k < kc; k++) {
                int r = 0;
                for (; r < rows; r++) d[r] = s[(size_t)r * n + k];
                for (; r < MR; r++) d[r] = 0.0f;
                d += MR;
            }
        }
    }
}

/* Packs rows [kb, ke) of the kc x nc block of B at (p0, j0) into NR-wide panels. */
static void pack_b(const float *B, int n, int p0, int kc, int j0, int nc,
                   int kb, int ke, float *restrict Bp)
{
    for (int k = kb; k < ke; k++) {
        const float *s = B + (size_t)(p0 + k) * n + j0;
        float *d = Bp + (size_t)k * NR;
        int jp = 0;
        for (; jp + NR <= nc; jp += NR)
            memcpy(d + (size_t)jp * kc, s + jp, NR * sizeof(float));
        if (jp < nc) {
            float *dd = d + (size_t)jp * kc;
            int c = nc - jp;
            memcpy(dd, s + jp, (size_t)c * sizeof(float));
            memset(dd + c, 0, (size_t)(NR - c) * sizeof(float));
        }
    }
}

typedef struct {
    const float *A, *B;
    float *C;
    float *Bp[2];
    int n, nt, kcb, ncb;
    int bar_count, bar_gen;
} job_t;

static job_t g_job;
static float g_Ap[MAXT][MC * KC] __attribute__((aligned(64)));

static void barrier_wait(job_t *j)
{
    int g = __atomic_load_n(&j->bar_gen, __ATOMIC_ACQUIRE);
    if (__atomic_add_fetch(&j->bar_count, 1, __ATOMIC_ACQ_REL) == j->nt) {
        __atomic_store_n(&j->bar_count, 0, __ATOMIC_RELAXED);
        __atomic_store_n(&j->bar_gen, g + 1, __ATOMIC_RELEASE);
    } else {
        long spins = 0;
        while (__atomic_load_n(&j->bar_gen, __ATOMIC_ACQUIRE) == g) {
            cpu_relax();
            if (++spins > (1L << 18)) { sched_yield(); spins = 0; }
        }
    }
}

static void run(int tid)
{
    job_t *j = &g_job;
    if (tid >= j->nt) return;
    const float *A = j->A, *B = j->B;
    float *C = j->C;
    int n = j->n, nt = j->nt, kcb = j->kcb, ncb = j->ncb;
    float *Ap = g_Ap[tid];
    float tmp[MR * NR] __attribute__((aligned(64)));

    int um = (n + MR - 1) / MR;
    int r0 = (int)((long)um * tid / nt) * MR, r1 = (int)((long)um * (tid + 1) / nt) * MR;
    if (r1 > n) r1 = n;
    int rows = r1 - r0;
    int mstep = MC;
    if (rows > 0) {
        int nmb = (rows + MC - 1) / MC;
        mstep = ((rows + nmb - 1) / nmb + MR - 1) / MR * MR;
    }

    int it = 0;
    for (int jc = 0; jc < n; jc += ncb) {
        int nc = n - jc < ncb ? n - jc : ncb;
        for (int pc = 0; pc < n; pc += kcb, it++) {
            int kc = n - pc < kcb ? n - pc : kcb;
            int acc = pc != 0;
            float *Bp = j->Bp[it & 1];

            int kb = (int)((long)kc * tid / nt), ke = (int)((long)kc * (tid + 1) / nt);
            pack_b(B, n, pc, kc, jc, nc, kb, ke, Bp);
            if (nt > 1) barrier_wait(j);

            for (int ic = r0; ic < r1; ic += mstep) {
                int mc = r1 - ic < mstep ? r1 - ic : mstep;
                pack_a(A, n, ic, mc, pc, kc, Ap);
                for (int jr = 0; jr < nc; jr += NR) {
                    int nr = nc - jr < NR ? nc - jr : NR;
                    const float *bp = Bp + (size_t)jr * kc;
                    float *cc = C + (size_t)ic * n + jc + jr;
                    for (int ir = 0; ir < mc; ir += MR) {
                        int mr = mc - ir < MR ? mc - ir : MR;
                        micro(kc, Ap + (size_t)ir * kc, bp, tmp);
                        if (mr == MR && nr == NR)
                            store_full(cc + (size_t)ir * n, n, tmp, acc);
                        else
                            store_edge(cc + (size_t)ir * n, n, tmp, mr, nr, acc);
                    }
                }
            }
        }
    }
}

/* Persistent pool. */
static pthread_mutex_t g_mu = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t g_cv = PTHREAD_COND_INITIALIZER;
static unsigned g_gen;
static int g_remaining;
static int g_pool = -1;

static void *pool_main(void *arg)
{
    int tid = (int)(long)arg;
    unsigned seen = 0;
    for (;;) {
        unsigned g;
        long spins = 0;
        while ((g = __atomic_load_n(&g_gen, __ATOMIC_ACQUIRE)) == seen) {
            if (++spins < SPIN_LIMIT) {
                cpu_relax();
            } else {
                pthread_mutex_lock(&g_mu);
                while (__atomic_load_n(&g_gen, __ATOMIC_ACQUIRE) == seen)
                    pthread_cond_wait(&g_cv, &g_mu);
                pthread_mutex_unlock(&g_mu);
                spins = 0;
            }
        }
        seen = g;
        run(tid);
        __atomic_sub_fetch(&g_remaining, 1, __ATOMIC_ACQ_REL);
    }
    return NULL;
}

#ifdef __linux__
/* Returns the first CPU listed in cpu's thread_siblings_list, or -1. */
static int core_rep(int cpu)
{
    char path[128];
    snprintf(path, sizeof path, "/sys/devices/system/cpu/cpu%d/topology/thread_siblings_list", cpu);
    FILE *f = fopen(path, "r");
    if (!f) return -1;
    int rep = -1;
    if (fscanf(f, "%d", &rep) != 1) rep = -1;
    fclose(f);
    return rep;
}
#endif

/* Counts physical cores in the affinity mask; falls back to logical CPUs. */
static int detect_threads(void)
{
    int n = 0;
#ifdef __linux__
    cpu_set_t cs;
    if (sched_getaffinity(0, sizeof cs, &cs) == 0) {
        n = CPU_COUNT(&cs);
        static unsigned char seen[CPU_SETSIZE];
        int cores = 0, ok = 1;
        for (int c = 0; c < CPU_SETSIZE; c++) {
            if (!CPU_ISSET(c, &cs)) continue;
            int r = core_rep(c);
            if (r < 0 || r >= CPU_SETSIZE) { ok = 0; break; }
            if (!seen[r]) { seen[r] = 1; cores++; }
        }
        if (ok && cores > 0) n = cores;
    }
#endif
    if (n <= 0) {
        long c = sysconf(_SC_NPROCESSORS_ONLN);
        n = c > 0 ? (int)c : 1;
    }
    if (n > MAXT) n = MAXT;
    return n;
}

static void pool_init(void)
{
    int hw = detect_threads();
    int created = 0;
    for (int t = 1; t < hw; t++) {
        pthread_t th;
        if (pthread_create(&th, NULL, pool_main, (void *)(long)t) != 0) break;
        pthread_detach(th);
        created++;
    }
    g_pool = created;
}

static float *g_Bbuf;
static size_t g_Bcap;

static void naive(const float *A, const float *B, float *C, int n)
{
    for (int i = 0; i < n; i++) {
        float *c = C + (size_t)i * n;
        for (int jj = 0; jj < n; jj++) c[jj] = 0.0f;
        for (int k = 0; k < n; k++) {
            float a = A[(size_t)i * n + k];
            const float *b = B + (size_t)k * n;
            for (int jj = 0; jj < n; jj++) c[jj] += a * b[jj];
        }
    }
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    if (g_pool < 0) pool_init();

    /* Balanced block sizes: no short trailing k or column block. */
    int nkb = (n + KC - 1) / KC;
    int kcb = (n + nkb - 1) / nkb;
    int njb = (n + NCMAX - 1) / NCMAX;
    int ncb = ((n + njb - 1) / njb + NR - 1) / NR * NR;

    size_t bsz = (size_t)KC * ncb;
    if (2 * bsz > g_Bcap) {
        free(g_Bbuf);
        g_Bbuf = aligned_alloc(64, 2 * bsz * sizeof(float));
        g_Bcap = g_Bbuf ? 2 * bsz : 0;
    }
    if (!g_Bbuf) { naive(A, B, C, n); return; }

    /* Give every thread at least four MR-row panels. */
    int nt = g_pool + 1;
    int um = (n + MR - 1) / MR;
    if (nt > um / 4) nt = um / 4;
    if (nt < 1) nt = 1;

    job_t *j = &g_job;
    j->A = A; j->B = B; j->C = C;
    j->Bp[0] = g_Bbuf; j->Bp[1] = g_Bbuf + bsz;
    j->n = n; j->nt = nt; j->kcb = kcb; j->ncb = ncb;
    j->bar_count = 0;

    if (nt == 1) {
        run(0);
        return;
    }

    __atomic_store_n(&g_remaining, g_pool, __ATOMIC_RELEASE);
    pthread_mutex_lock(&g_mu);
    __atomic_add_fetch(&g_gen, 1, __ATOMIC_ACQ_REL);
    pthread_cond_broadcast(&g_cv);
    pthread_mutex_unlock(&g_mu);

    run(0);

    while (__atomic_load_n(&g_remaining, __ATOMIC_ACQUIRE) != 0)
        cpu_relax();
}
